values ('fuldkornspasta-med-kylling-og-tomat', 'Fuldkornspasta med kylling og tomat', 'Fuldkornspasta i tomatsauce med stegt kylling, spinat, basilikum og parmesan.', 4, 10, 25, array['dinner']::public.meal_slot[], array['Kog pastaen efter anvisningen på pakken.', 'Steg kyllingebryst i tern i olien, til det er gennemstegt, og tag det af panden.', 'Svits hakket løg og hvidløg, tilsæt hakkede tomater og lad saucen simre i 10 minutter.', 'Vend kylling, spinat og pasta i saucen, til spinaten falder sammen.', 'Server med revet parmesan og frisk basilikum.']::text[], 'beginner', array['fitness', 'italiensk']::text[])
