values ('roed-karry-med-kylling-og-jasminris', 'Rød karry med kylling', 'Cremet rød karry med kylling, peberfrugt og sukkerærter serveret med jasminris.', 4, 15, 20, array['dinner']::public.meal_slot[], array['Kog jasminrisene efter anvisningen på pakken.', 'Steg karrypastaen i olien i en gryde i et minut, til den dufter.', 'Tilsæt kyllingen i tern, og steg den til den har taget farve.', 'Hæld kokosmælken ved, og lad karryen simre i 10 minutter.', 'Kom peberfrugt og sukkerærter i de sidste 3 minutter, og smag til med fiskesauce og limesaft.', 'Server karryen med ris og evt. basilikum.']::text[], 'beginner', array['thai', 'asiatisk']::text[])
