values ('tom-kha-kokossuppe-med-kylling', 'Tom kha med kylling', 'Duftende kokossuppe med kylling, champignon, ingefær og lime samt risnudler.', 4, 15, 20, array['lunch', 'dinner']::public.meal_slot[], array['Bring 8 dl vand i kog med bouillonterning, ingefær i skiver og chili.', 'Tilsæt kokosmælk og kyllingen i tynde strimler, og lad det simre i 8 minutter.', 'Kom champignon i skiver i, og kog videre i 3 minutter.', 'Læg imens risnudlerne i blød i kogende vand, og fordel dem i skåle.', 'Smag suppen til med fiskesauce og limesaft, og hæld den over nudlerne med koriander.']::text[], 'beginner', array['thai', 'asiatisk']::text[])
