values ('larb-gai-med-spidskaal-og-ris', 'Larb gai med salat', 'Let og syrlig salat af finthakket kylling med lime, rødløg og krydderurter i spidskålsblade.', 2, 20, 10, array['lunch', 'dinner']::public.meal_slot[], array['Kog jasminrisene efter anvisningen på pakken.', 'Hak kyllingen meget fint med en kniv, og steg den i olien, til den er gennemstegt.', 'Tag panden af varmen, og vend rødløg, chili, fiskesauce og limesaft i.', 'Vend til sidst koriander og forårsløg i kødet.', 'Server larb i spidskålsblade med agurk og ris ved siden af.']::text[], 'intermediate', array['thai', 'asiatisk', 'fitness']::text[])
