values ('thai-basilikum-kylling-med-spejlaeg', 'Thai basilikum-kylling', 'Hurtig, stærk wok med kylling, hvidløg, chili og masser af basilikum, toppet med spejlæg.', 2, 10, 15, array['dinner']::public.meal_slot[], array['Kog jasminrisene efter anvisningen på pakken.', 'Steg hvidløg og chili kort i halvdelen af olien på en varm wok.', 'Tilsæt kyllingen i små stykker og peberfrugt, og steg til kødet er gennemstegt.', 'Rør sojasauce, fiskesauce og honning i, og vend basilikum i til sidst.', 'Steg spejlæg i resten af olien, og server ovenpå kylling og ris.']::text[], 'beginner', array['thai', 'asiatisk', 'fitness']::text[])
