values ('kyllingespyd-med-jordnoeddesauce', 'Kyllingespyd med jordnøddesauce', 'Marinerede kyllingespyd med cremet jordnøddesauce, jasminris og frisk agurk.', 4, 25, 15, array['dinner']::public.meal_slot[], array['Skær kyllingen i strimler, og vend dem med halvdelen af sojasaucen, karry og olie.', 'Sæt kødet på spyd, og grill eller steg dem i 4–5 minutter på hver side.', 'Kog jasminrisene efter anvisningen på pakken.', 'Varm jordnøddesmør, kokosmælk, resten af sojasaucen, honning og limesaft sammen til en jævn sauce.', 'Server spyddene med sauce, ris og agurk i skiver.']::text[], 'intermediate', array['thai', 'asiatisk']::text[])
