insert into public.recipes (slug, name_da, description_da, servings, prep_minutes, cook_minutes, meal_types, instructions_da, difficulty, cuisines)
values ('thai-stegte-ris-med-rejer', 'Thailandske stegte ris med rejer', 'Stegte jasminris med rejer, æg, ærter og forårsløg – perfekt til rester af ris.', 2, 10, 10, array['lunch', 'dinner']::public.meal_slot[], array['Kog risene i forvejen, og lad dem køle helt af, gerne dagen før.', 'Steg hakket løg i olien på en varm wok, og tilsæt rejerne, til de er lyserøde.', 'Skub det til side, og rør æggene sammen på panden.', 'Tilsæt ris og ærter, og steg det hele godt igennem under omrøring.', 'Smag til med fiskesauce og sojasauce, og server med forårsløg, agurk og limebåde.']::text[], 'beginner', array['thai', 'asiatisk']::text[])
on conflict (slug) do update set cuisines = excluded.cuisines;

