insert into public.recipes (slug, name_da, description_da, servings, prep_minutes, cook_minutes, meal_types, instructions_da, difficulty, cuisines)
values ('thai-nudelsalat-med-kylling', 'Thai nudelsalat med kylling', 'Sprød nudelsalat med kylling, rå grøntsager, jordnødder og en frisk lime-chili-dressing.', 2, 20, 10, array['lunch', 'dinner']::public.meal_slot[], array['Steg kyllingen i en tør eller let smurt pande, til den er gennemstegt, og skær den i strimler.', 'Læg risnudlerne i blød i kogende vand, skyl dem kolde, og lad dem dryppe af.', 'Snit agurk, gulerødder og spidskål fint.', 'Rør limesaft, fiskesauce, honning, sesamolie og finthakket chili sammen til en dressing.', 'Vend nudler, grøntsager, kylling og dressing sammen, og top med jordnødder og koriander.']::text[], 'beginner', array['thai', 'asiatisk']::text[])
