values ('massaman-inspireret-karry-med-kartofler', 'Massaman-inspireret karry', 'Mild og fyldig karry med kyllingelår, kartofler og jordnødder i kokosmælk.', 4, 20, 35, array['dinner']::public.meal_slot[], array['Skær kartofler i store tern og løg i både.', 'Steg karrypasta og karry kort i en gryde, og brun kyllingelårene i tern heri.', 'Tilsæt kokosmælk, 2 dl vand, kartofler og løg, og lad det simre under låg i 25 minutter.', 'Rør jordnødder og honning i, og smag til med fiskesauce og limesaft.', 'Server karryen, gerne med lidt koriander på toppen.']::text[], 'intermediate', array['thai', 'asiatisk']::text[])
