values ('teriyaki-laks-med-ris-og-broccoli', 'Teriyaki-laks med ris', 'Laks glaseret i hjemmelavet teriyakisauce med jasminris og dampet broccoli.', 2, 10, 20, array['dinner']::public.meal_slot[], array['Kog jasminrisene efter anvisningen på pakken.', 'Rør sojasauce, honning, revet ingefær og presset hvidløg sammen.', 'Steg laksen på skindsiden i 4 minutter, vend den, og hæld saucen på panden.', 'Lad saucen boble ind til et blankt glaze, mens laksen bliver færdig.', 'Damp broccolien i 4 minutter, og server med laks, ris, forårsløg og et skvæt sesamolie.']::text[], 'beginner', array['asiatisk']::text[])
