values ('sushi-bowl-med-laks', 'Sushi-bowl med laks', 'Skål med ris, stegt laks, edamame, agurk, avocado og gulerod med sojadressing.', 2, 15, 15, array['lunch', 'dinner']::public.meal_slot[], array['Kog jasminrisene, og lad dem køle lidt af.', 'Steg laksen i en tør pande i 3–4 minutter på hver side, og del den i flager.', 'Kog edamamebønnerne i 3 minutter, og skær agurk, avocado og gulerod i tynde stykker.', 'Rør sojasauce, honning, limesaft og sesamolie sammen til en dressing.', 'Anret ris i skåle med laks og grøntsager, og hæld dressingen over.']::text[], 'beginner', array['asiatisk']::text[])
