values ('roed-linse-dal-med-spinat', 'Indisk dal med røde linser', 'Cremet og krydret dal af røde linser, tomat og kokosmælk med spinat og basmatiris.', 4, 10, 30, array['lunch', 'dinner']::public.meal_slot[], array['Svits hakket løg, hvidløg og revet ingefær i olien, og rør karry og spidskommen i.', 'Tilsæt skyllede linser, hakkede tomater, kokosmælk og 5 dl vand.', 'Lad dallen simre i 20–25 minutter under omrøring, til linserne er møre.', 'Kog imens basmatirisene efter anvisningen på pakken.', 'Vend spinaten i dallen, smag til med citronsaft, og server med ris.']::text[], 'beginner', array['asiatisk']::text[])
