values ('kylling-tikka-inspireret-med-ris', 'Kylling tikka-inspireret', 'Skyrmarineret kylling i krydret tomatsauce med basmatiris – et lettere bud på tikka masala.', 4, 20, 25, array['dinner']::public.meal_slot[], array['Vend kyllingen i tern med skyr, halvdelen af karryen, paprika og presset hvidløg, og lad den marinere i mindst 15 minutter.', 'Steg kyllingen i olien i en gryde, til den har fået farve.', 'Tilsæt hakket løg, revet ingefær, resten af karryen og spidskommen, og svits et minut.', 'Hæld hakkede tomater og creme fraiche ved, og lad retten simre i 15 minutter.', 'Kog imens basmatirisene, og server med koriander.']::text[], 'intermediate', array['asiatisk', 'fitness']::text[])
